blob=json.dumps(obj,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
page=r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Team Unicorn · Destination-Aware Gait Lab 0.3</title>
<style>
:root{color-scheme:light;--ink:#202934;--mute:#687585;--border:#e2e6ec;--paper:#fff;--bg:#f4f6f8;--blue:#2563eb;--teal:#0f8e80;--gold:#d59c42;font-family:system-ui,-apple-system,'Apple SD Gothic Neo','Malgun Gothic',sans-serif}*{box-sizing:border-box}body{background:var(--bg);color:var(--ink);margin:0}main{max-width:1180px;margin:auto;padding:30px 20px 50px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:11px;font-weight:800;color:var(--mute)}h1{font-size:clamp(27px,4.7vw,46px);letter-spacing:-.05em;margin:8px 0 13px}h2{font-size:20px;margin:0 0 16px;letter-spacing:-.025em}p{line-height:1.65}header p{max-width:960px}.muted{color:var(--mute)}.small{font-size:12px;line-height:1.6}.card{border-radius:19px;background:var(--paper);border:1px solid var(--border);padding:23px;margin:17px 0;box-shadow:0 5px 22px #293c4d08}.controls{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}label{font-weight:700;font-size:12px;display:block;margin-bottom:7px;color:#445063}select,input{font:inherit;width:100%;padding:11px;border:1px solid #cfd5dc;border-radius:10px;background:#fff;color:var(--ink)}input[type=range]{padding:0;border:0;accent-color:var(--teal)}input[type=search]{margin-bottom:10px}.buttons{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}button{font:inherit;background:#f7f8fa;color:var(--ink);border:1px solid #d1d7df;border-radius:10px;cursor:pointer;padding:9px 13px}button:hover,button:focus-visible{background:#e9f1f5}button.primary{background:#192b41;color:#fff;border-color:#192b41}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:15px 0}.metric{background:#f5f7f9;border-radius:12px;padding:16px}.metric .num{font-size:clamp(19px,3vw,29px);font-weight:750;letter-spacing:-.035em;margin:5px 0}.metric .unit{font-size:13px;font-weight:400}.metric .name{font-size:12px;color:#626b75}.metric .sub{font-size:11px;color:#626b75}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(250px,2fr);gap:14px}.subcard{border-radius:14px;background:#f5f7f9;padding:16px}.headline{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.leg{border:1px solid #cdd9e1;border-radius:999px;padding:6px 10px;font-size:13px;background:#eaf3fa;font-weight:700}.legs{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.path{display:flex;flex-wrap:wrap;gap:7px;align-items:center;line-height:1.5;margin:8px 0}.pulse{padding:5px 8px;border-radius:8px;border:1px solid #cbd6e1;font-size:12px;background:#fff}.pulse.fine{background:#fff5e2;border-color:#ead19b}.big{font-size:24px;font-weight:750}.bar{width:100%;height:12px;background:#e8ecf0;border-radius:99px;overflow:hidden;display:flex;margin:12px 0}.seg{height:100%}.rows{overflow-x:auto;max-height:480px;overflow-y:auto;border:1px solid var(--border);border-radius:12px}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th,td{padding:11px;border-bottom:1px solid #e5e9ee;text-align:right}th{position:sticky;top:0;background:#edf1f6;font-size:11px;color:#536072;z-index:1}td:first-child,th:first-child{text-align:left}tbody tr{cursor:pointer}tbody tr:hover{background:#edf6fa}tbody tr.active{background:#dff3ed}tbody tr:last-child td{border-bottom:0}td.prime{color:#08786a;font-weight:700}.note{padding:13px 16px;border-left:3px solid #b9c8d5;background:#f7f9fa;font-size:12px;line-height:1.7;border-radius:4px}.tag{border-radius:999px;padding:5px 10px;background:#ebf1f6;color:#38506a;font-size:12px;font-weight:700}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}summary{cursor:pointer;font-weight:750}details{margin:12px 0}code,.formula{font-family:ui-monospace,Consolas,monospace;font-size:12px}.formula{padding:12px;border-radius:10px;background:#edf1f5;overflow-x:auto}.legend{display:flex;gap:13px;flex-wrap:wrap;font-size:12px;margin-top:4px}.dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:5px}.routeSvg{width:100%;background:#f8fafb;border-radius:12px;min-height:168px;overflow:visible}.footnote{color:var(--mute);font-size:11px;line-height:1.7}a{color:var(--blue)}
@media(max-width:800px){main{padding:20px 11px}.card{padding:17px 13px}.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.layout,.grid2{grid-template-columns:1fr}}
</style></head><body><main>
<header><div class="eyebrow">Self-Expanding Integer Universe · computational toy experiment</div><h1>🦄 Team Unicorn · Gait Lab 0.3</h1><p><b>2호부터 100호까지 목적지 선공개.</b> HQ는 알려진 최종 목적지 <b>n</b>에 맞춰 다리 개수·소수 라벨과 gait를 역설계한다. 유니콘은 원점에서 <b>n−1</b>까지 이동한 뒤 <b>+1</b>로 돌을 놓고, 원점으로 돌아와 다음 세대에 정보를 전한다.</p><div class="small muted">99 destinations · 209 architectures × coordination settings × leg-availability rules · deterministic exhaustive selection within stated rules · no networking needed</div></header>
<section class="card"><h2>01 · HQ 설계 조건</h2><div class="controls">
<div><label for="n">유니콘 / 최종 목적지</label><input id="n" type="range" min="2" max="100" value="37"><div class="small"><b id="nVal">37</b>번째 돌 · 이전 돌 <b id="prevVal">36</b></div></div>
<div><label for="gamma">다리 협응 비용</label><select id="gamma"><option value="light">낮음 (γ=0.06 s)</option><option value="medium" selected>중간 (γ=0.14 s)</option><option value="heavy">높음 (γ=0.24 s)</option></select></div>
<div><label for="availability">HQ의 소수 부품 정보</label><select id="availability"><option value="inherited" selected>계승된 부품만 · p ≤ n−1</option><option value="preloaded">초기부터 소수 2~13 전부</option></select></div>
<div><label for="objective">최적화 대상</label><select id="objective"><option value="roundtrip" selected>탄생 + 왕복 + 마지막 +1</option><option value="outbound">탄생 + 출발 + 마지막 +1</option></select></div>
</div><div class="buttons"><button data-go="2">2호</button><button data-go="13">13호</button><button data-go="17">17호</button><button data-go="37">37호</button><button data-go="50">50호</button><button data-go="97">97호</button><button data-go="100">100호</button><button id="next">다음 유니콘 →</button></div></section>
<section class="card"><div class="headline"><h2>02 · 선택된 최적 유니콘</h2><span class="tag" id="primeFlag">결과</span></div><div id="metrics" class="metrics"></div>
<div class="layout"><div class="subcard"><b>정수 징검다리 · outward journey</b><div id="route"></div><div class="small muted">파란색: 소수 라벨 다리들을 동시에 사용하는 가상 pulse · 금색: 느린 +1 보정 · 초록색: 마지막 +1로 돌 놓기</div><div class="legs" id="legs"></div><div id="steps" class="path"></div></div>
<div class="subcard"><b>시간 비용 내역</b><div id="costbar" class="bar"></div><div id="breakdown" class="small"></div><div style="margin-top:12px"><b>전체 99개 목적지 통계</b><div id="stats" class="small" style="line-height:1.85;margin-top:5px"></div></div></div></div>
<div class="note" style="margin-top:15px"><b>Important:</b> 동작 하나에 사용된 다리의 소수 라벨 합계를 이동거리로 취급하는 가상 규칙이야. 이 규칙은 소수–보폭 연결을 <b>가정</b>하며 입증하지 않아. 다리의 위상, 주파수, 생체역학, 실제 3D 파동은 아직 미구현이야.</div></section>
<section class="card"><div class="headline"><h2>03 · 전체 유니콘 2~100</h2><button class="primary" id="save">현재 조건 99개 결과 CSV</button></div><input type="search" id="filter" placeholder="목적지 또는 다리 조합 검색 (예: 37, 11-13)"><div class="rows"><table><thead><tr><th>Unicorn</th><th>유형</th><th>다리 라벨</th><th>k</th><th>왕복/편도 총시간</th><th>단일 다리 대비 절약</th><th>출발 pulse</th></tr></thead><tbody id="table"></tbody></table></div><p class="footnote">표의 모든 행은 명시한 209종 중 허용되는 모든 설계를 비교해 최저 총비용을 고른 결과야. 같은 소수의 다리를 여러 개 사용하는 설계도 허용한다. 별도의 유니콘 제작 방법 개선, 3D 재조직, 실제 Fourier 위상 최적화는 아직 포함하지 않았다.</p></section>
<section class="card"><h2>04 · 산술적 관계와 해석</h2><div class="grid2"><div><h3 style="font-size:15px">기본 생성 규칙</h3><div class="formula">n번째 유니콘 → 목표 n\n원점 → (n−1) : 최적화된 gait\n(n−1) → n : 고정된 최종 +1\nn → 원점 : 같은 gait의 비용으로 역방향 귀환\n총비용 = 탄생 + 출발 + 최종+1 + 귀환</div><p class="small muted">내부 이동의 정밀한 +1 보정은 마지막 +1과 별개이며, 시간이 더 많이 드는 일반 보정 동작으로 취급해. 2호를 출발시키는 데에는 소수 2 부품이 미리 준비돼 있다고 가정한다.</p></div><div><h3 style="font-size:15px">가상 운동 법칙</h3><div class="formula">한 pulse 거리 = Σ 활성 다리의 소수 라벨 pᵢ\n시간 τ = maxᵢ (0.10 + 0.045√pᵢ)\n        + γ(r−1)² + 0.015(k−r) + 0.015(k−1)\n탄생 시간 = 0.07 Σ√pᵢ + 0.10 k²</div><p class="small muted">k = 전체 다리 수, r = 이번 pulse에서 움직인 다리 수. Pulse는 직렬 실행하며, 하나의 움직임이 끝나야 다음 움직임을 시작할 수 있어. 각 구간의 유효 주파수는 1/τ, 유효 이동거리는 Σpᵢ이므로 λf 형태의 평균속도가 가능하지만, 실제 푸리에 합성은 아니야.</p></div></div>
<details><summary>코드·데이터에서 아직 결정하지 않은 것들</summary><p class="small">소수 p와 실제 다리 길이·근력·주기 사이의 물리적 매핑, 여러 다리의 추진력 결합 법칙, 위상/주파수의 연속적 최적화, 계승정보량과 HQ의 설계비용, 복귀하면서 일어나는 과거 구조 재조직, 엔트로피, 병렬 설계 비용과 유니콘의 진화는 미구현이다. 따라서 최적이라는 결과는 지정된 다리 후보·행동 목록·비용함수 안에서만 성립한다.</p></details>
<details><summary>소수가 나오면 더 빨라지는가?</summary><p class="small">유니콘의 번호 n과 이전 돌 n−1의 소인수분해는 데이터에서 볼 수 있지만, 이 모형은 소수의 위치를 예측하지 않는다. 소수 레이블 자체를 다리에 넣었기 때문에, 소수의 활용을 새롭게 발견했다고 주장할 수 없다. 연속 정수의 소인수 관계와 설계 선택 사이에 독립적으로 재현 가능한 효과가 있는지는 대조군과 매핑 변경을 통해 따로 시험해야 한다.</p></details></section>
<footer class="footnote">Source audit: Unicorn Gait Lab 0.2의 명시적 동작 비용·초당 움직임 모델과 현재 대화의 Team Unicorn 목적지 선지정 및 바통 전달 규칙을 기반으로 재설계했다. 0.2를 그대로 사용하지는 않았다. 데이터는 Python 3로 모든 후보를 계산하고 각 경로를 재계산해 확인했다. 이 파일은 실험용 수학적 추상 모형으로 실제 동물, 소수의 물리적 생성, Fourier wave simulation의 검증이 아니다.</footer>
</main><script id="modeldata" type="application/json">__DATA__</script><script>
'use strict';
const DATA=JSON.parse(document.getElementById('modeldata').textContent);const $=id=>document.getElementById(id);const num=x=>Number(x).toFixed(3).replace(/\.000$/,'');
let selected=37;
function config(){return {gamma:$('gamma').value,availability:$('availability').value,objective:$('objective').value};}
function regime(){let c=config();return DATA.regimes[c.gamma][c.availability][c.objective];}
function rowAt(n){return regime().results[n-2];}
function routeSVG(r){let pts=[{value:0,type:'origin'}];for(const a of r.path)pts.push({value:a.to,type:a.fine?'fine':'normal'});pts.push({value:r.destination,type:'last'});
 const W=920,H=177,L=43,R=875,scale=v=>L+(R-L)*v/Math.max(2,r.destination),y=101;
 const circles=pts.map((p,i)=>`<circle cx="${scale(p.value)}" cy="${y}" r="${i===pts.length-1?7:5}" fill="${p.type==='last'?'#0f8e80':p.type==='fine'?'#cf9a42':p.type==='origin'?'#354966':'#2563eb'}"/><text x="${scale(p.value)}" y="${(i%2?120:84)}" font-size="13" text-anchor="middle" fill="#293c4d">${p.value}</text>`).join('');
 const segments=pts.slice(1).map((p,i)=>{let x1=scale(pts[i].value),x2=scale(p.value),by=y-20-21*(i%2);let col=p.type==='last'?'#0f8e80':p.type==='fine'?'#cf9a42':'#2563eb';return `<path d="M${x1} ${y}Q${(x1+x2)/2} ${by} ${x2} ${y}" stroke="${col}" stroke-width="3" fill="none"/><text x="${(x1+x2)/2}" y="${by-4}" font-size="11" text-anchor="middle" fill="${col}">+${p.value-pts[i].value}</text>`;}).join('');
 return `<svg class="routeSvg" viewBox="0 0 ${W} ${H}" role="img" aria-label="0에서 ${r.previous_rock}까지 발걸음을 밟고 최종 +1로 ${r.destination}에 도착"><line x1="${L}" y1="${y}" x2="${R}" y2="${y}" stroke="#c7d0da" stroke-width="2"/>${segments}${circles}<text x="${L}" y="148" font-size="12" fill="#526277">HQ origin</text><text x="${R}" y="148" font-size="12" text-anchor="end" fill="#0f8e80">Rock n=${r.destination}</text></svg>`;
}
function metric(name,val,sub){return `<div class="metric"><div class="name">${name}</div><div class="num">${val}</div><div class="sub">${sub}</div></div>`}
function draw(){const r=rowAt(selected),model=regime(),c=config();$('n').value=selected;$('nVal').textContent=selected;$('prevVal').textContent=selected-1;$('primeFlag').textContent=r.is_prime_target?'목적지: 소수':'목적지: 합성수';
 $('metrics').innerHTML=metric('최적 다리 개수',r.k+'개','레그 라벨: '+r.legs.join(' · '))+metric('총 임무 시간',num(r.total)+' s','탄생 및 '+(c.objective==='roundtrip'?'왕복':'출발')+' 포함')+metric('기존 돌까지 이동',num(r.outbound)+' s',`${r.gait_steps} pulses · 끝에 +1`)+metric('단일 다리보다',num(r.gain_vs_single)+' s','더 짧은 임무시간');
 $('route').innerHTML=routeSVG(r);$('legs').innerHTML=r.legs.map((p,i)=>`<span class="leg">Leg ${i+1}: prime ${p}</span>`).join('');
 $('steps').innerHTML=r.path.map(a=>`<span class="pulse ${a.fine?'fine':''}">${a.label}: +${a.jump}</span>`).join('')+`<span class="pulse" style="border-color:#0f8e80;color:#0f8e80">최종 +1 → ${r.destination}</span>`;
 const parts=[{n:'탄생',v:r.birth,c:'#8290a4'},{n:'출발',v:r.outbound,c:'#2563eb'},{n:'최종 +1',v:r.final_plus_one,c:'#0f8e80'},{n:'귀환',v:r.return,c:'#d49b42'}];
 $('costbar').innerHTML=parts.map(p=>`<span class="seg" style="width:${100*p.v/r.total}%;background:${p.c}"></span>`).join('');$('breakdown').innerHTML=parts.map(p=>`<div style="display:flex;justify-content:space-between;margin:5px 0"><span><span class="dot" style="background:${p.c}"></span>${p.n}</span><b>${num(p.v)}s</b></div>`).join('');
 const s=model.stats;$('stats').innerHTML=`최적 설계: 1다리 ${s.k_counts['1']||0}회 · 2다리 ${s.k_counts['2']||0}회 · 3다리 ${s.k_counts['3']||0}회 · 4다리 ${s.k_counts['4']||0}회<br>평균 총시간: <b>${num(s.mean_total)}s</b><br>목적지별 한 다리만 허용한 경우보다 <b>${num(s.single_gain_pct)}%</b> 절약<br>모든 부품 선공급 조건의 단일 고정설계 ${s.fixed_legs.join('·')}와의 비교는 인과적 부품 제한 상황에서는 동일 조건이 아님.`;
 renderTable();}
function renderTable(){let term=$('filter').value.trim().toLowerCase();const a=regime().results.filter(r=>String(r.destination).includes(term)||r.legs.join('-').includes(term));$('table').innerHTML=a.map(r=>`<tr data-n="${r.destination}" class="${r.destination===selected?'active':''}"><td>#${r.unicorn} → ${r.destination}</td><td class="${r.is_prime_target?'prime':''}">${r.is_prime_target?'소수':'합성수'}</td><td>${r.legs.join('–')}</td><td>${r.k}</td><td>${num(r.total)} s</td><td>${num(r.gain_vs_single)} s</td><td>${r.gait_steps}회</td></tr>`).join('');$('table').querySelectorAll('tr[data-n]').forEach(el=>el.addEventListener('click',()=>{selected=+el.dataset.n;draw();window.scrollTo({top:210,behavior:'smooth'});}));}
function save(){const c=config();let rows=regime().results;let head=['unicorn','destination','previous_rock','is_prime_target','legs','k','birth','outbound','final_plus_one','return','total','gait_steps','fine_steps','gain_vs_single'];const body=[head.join(','),...rows.map(r=>head.map(h=>h==='legs'?`"${r.legs.join('-')}"`:r[h]).join(','))].join('\r\n');let bl=new Blob(['\ufeff'+body],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(bl),a=document.createElement('a');a.href=url;a.download=`unicorn_destinations_2-100_${c.gamma}_${c.availability}_${c.objective}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('n').addEventListener('input',e=>{selected=Number(e.target.value);draw()});for(let x of ['gamma','availability','objective'])$(x).addEventListener('change',draw);$('filter').addEventListener('input',renderTable);document.querySelectorAll('button[data-go]').forEach(b=>b.addEventListener('click',()=>{selected=Number(b.dataset.go);draw()}));$('next').addEventListener('click',()=>{selected=selected===100?2:selected+1;draw()});$('save').addEventListener('click',save);draw();
</script></body></html>'''
(root/'index.html').write_text(page.replace('__DATA__',blob),encoding='utf8')
print('wrote',root/'index.html', (root/'index.html').stat().st_size)
